pub fn rentals_purpose() -> &'static str {
    "Rental kits for kayak, bike, snowshoe, locker, grill, and canoe equipment issued through visitor desks and concession points."
}

pub fn rentals_summary() -> String {
    let campsites = rental_kits();
    let shard_total: u32 = campsites.iter().map(|item| item.shard).sum();
    let record_total: u32 = campsites.iter().map(|item| item.survey).sum();
    let pressure_total: u32 = campsites.iter().map(|item| item.pressure).sum();
    format!("rentals count={} shard={} rec={} pressure={}", campsites.len(), shard_total, record_total, pressure_total)
}

pub fn rentals_family_window(family: &str, limit: usize) -> Vec<RentalKit> {
    rental_kits().into_iter().filter(|item| item.family == family).take(limit).collect()
}

pub fn rentals_weighted_total(seed: u32) -> u64 {
    rental_kits().into_iter().enumerate().map(|(index, item)| {
        let bias = (seed as u64 + index as u64 % 31) + 1;
        bias * (item.shard as u64 + item.survey as u64 * 3 + item.pressure as u64 * 5)
    }).sum()
}

pub fn rentals_nearest(shard: u32, survey: u32) -> Option<RentalKit> {
    rental_kits().into_iter().min_by_key(|item| {
        let a = item.shard.abs_diff(shard) as u64;
        let b = item.survey.abs_diff(survey) as u64;
        a * 7 + b * 3 + item.pressure as u64
    })
}

pub fn rentals_note_digest(limit: usize) -> Vec<String> {
    rental_kits().into_iter().take(limit).map(|item| format!("{}:{}:{}", item.key, item.family, item.note)).collect()
}
